{
  "decisions": [
    {
      "requirement_id": "KDH-101",
      "methods": [
        "Test"
      ],
      "rationale": "Hareketsizlik kilidi ve FIDO2/PIN ile yeniden kimlik doğrulama akışının, sistem çalıştırılarak ve girdi verilerek gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KDH-102",
      "methods": [
        "Test"
      ],
      "rationale": "Oturumun belirlenen koşullarda otomatik sonlandırılması, sistem üzerinde süre ve koşul senaryoları çalıştırılarak doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-103",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Denetim kayıtlarının içerdiği alanların doğruluğu testle, yapısal uygunluğunun ise kayıtların gözle denetlenmesiyle kontrol edilmelidir."
    },
    {
      "requirement_id": "KDH-104",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "Zaman damgalarının UTC formatında ve doğru ayrıntı düzeyinde üretilip üretilmediği testle, kayıtların yapısının ise inceleme ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-105",
      "methods": [
        "Test"
      ],
      "rationale": "Yetkisiz erişim, değişiklik veya silme girişimlerinin algılanması ve uyarı mekanizmasının çalışması, sistem üzerinde saldırı senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-106",
      "methods": [
        "Test"
      ],
      "rationale": "Kimlik doğrulama bilgilerinin ekranda gizlenip gizlenmediği, kullanıcı girdisi verildiğinde arayüzün gözlemlenmesiyle test edilmelidir."
    },
    {
      "requirement_id": "KDH-107",
      "methods": [
        "Test"
      ],
      "rationale": "Hassas işlemler öncesi tazelik süresi içinde yeniden kimlik doğrulama zorunluluğunun uygulanıp uygulanmadığı, işlem akışı çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test",
        "Analiz"
      ],
      "rationale": "İletişim güvenliğinin sağlandığı ağ trafiği yakalama ile test edilmeli, şifreleme yapılandırmasının yeterliliği ise analiz ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
      "rationale": "Geçersiz ve istismar amaçlı girdilerin reddedilmesi, sistem üzerinde çeşitli girdi senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-110",
      "methods": [
        "Test"
      ],
      "rationale": "Hata mesajlarının kullanıcıya gösterilen içeriği ve yetkili personele iletilen ayrıntılı logların doğruluğu, hata senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-111",
      "methods": [
        "Test"
      ],
      "rationale": "Oturum sonu uyarısı, taslak kaydetme ve veri kaybı olmadan devam etme akışının çalışması, sistem üzerinde senaryo çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-112",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "CAPTCHA kullanılmadığı ve bot doğrulama akışının çalıştığı testle, erişilebilirlik uyumunun ise inceleme ile doğrulanmalıdır."
    },
    {
      "requirement_id": "KDH-113",
      "methods": [
        "Test"
      ],
      "rationale": "Ödeme sonucunun yalnızca imzalı bildirimle kabul edilmesi ve belirsiz durumların yönetimi, entegrasyon senaryoları çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-114",
      "methods": [
        "Test"
      ],
      "rationale": "AAL2 altı doğrulama düzeyinde oturumun sınırlı kipte açılması ve veri gizlenmesi, farklı kimlik belirteçleri ile test edilmelidir."
    },
    {
      "requirement_id": "KDH-115",
      "methods": [
        "Test"
      ],
      "rationale": "Parola geçerlilik süresinin yalnızca belirli kullanıcılar için uygulanması ve ele geçirme kanıtında zorunlu değişiklik, senaryo çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-116",
      "methods": [
        "Test"
      ],
      "rationale": "TOTP kodlarının yalnızca geçerli ve bir önceki adımda kabul edilmesi, farklı zaman damgalarıyla kod üretilerek test edilmelidir."
    },
    {
      "requirement_id": "KDH-117",
      "methods": [
        "Test"
      ],
      "rationale": "Başarısız deneme eşiğinde doğrulayıcının devre dışı bırakılması ve hesap kurtarma akışı, tekrarlı başarısız giriş denemeleriyle test edilmelidir."
    },
    {
      "requirement_id": "KDH-118",
      "methods": [
        "Test"
      ],
      "rationale": "Farklı AAL düzeylerinde hareketsizlik sonrası yeniden kimlik doğrulama akışlarının ve oturum sırrı yönetiminin çalışması, senaryo çalıştırılarak test edilmelidir."
    },
    {
      "requirement_id": "KDH-119",
      "methods": [
        "Test"
      ],
      "rationale": "Eşzamanlı oturum sınırının aşılması durumunda en eski oturumun sonlandırılması ve bildirim/SIEM iletimi, çoklu oturum senaryolarıyla test edilmelidir."
    },
    {
      "requirement_id": "KDH-120",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut ve sayı sınırlarının denetlenmesi ve ret mesajlarının içeriği, farklı dosya yüklemeleri ile test edilmelidir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates the availability of specific authentication options, which is verified by executing the login flow and observing the presented choices."
    },
    {
      "requirement_id": "KDH-002",
      "methods": [
        "Test"
      ],
      "rationale": "The system's ability to enforce multi-factor or two-factor authentication at AAL2 is verified by attempting logins with valid and invalid factor combinations."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "Periodic reauthentication behavior based on inactivity and overall timeouts is verified by simulating user sessions and observing session termination or re-prompting."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of notifications upon account recovery is verified by triggering the recovery process and checking for the delivery of the notification."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "The distribution of notifications to registered addresses (excluding postal) is verified by triggering a notification event and checking the delivery logs or inboxes."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The independence of the VBP session from the e-Devlet assertion validity window is verified by maintaining a VBP session after the e-Devlet assertion expires."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The content of the assertion request, specifically the inclusion of the VBP identifier and cryptographic nonce, is verified by inspecting the network traffic or code implementation."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of the assertion audience is verified by attempting to inject an assertion intended for a different relying party and observing the rejection."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "The enforcement of the binding process for changing SMS phone numbers is verified by attempting to change the number and observing the required authentication steps."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The ability to bind multiple authenticators is verified by adding more than one authenticator to a test account and confirming their presence."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "The required authentication level for binding new authenticators is verified by attempting to bind an authenticator at different AAL levels and observing the system's response."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of independent notifications upon adding an authenticator is verified by adding a new authenticator and checking for the notification via a separate channel."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The invalidation of confirmation codes after use is verified by using a code successfully and then attempting to reuse it, expecting a rejection."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of assertion signatures is verified by presenting an assertion with an invalid or tampered signature and observing the rejection."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "Replay protection is verified by submitting the same valid assertion twice and observing that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The initiation of federation transactions by VBP as the RP is verified by inspecting the sequence of network requests or the code logic for the federation flow."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of information leakage during proofing is verified by submitting mismatched self-asserted information and observing that the error message does not reveal which specific attribute failed."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "The validation of core attributes against authoritative sources or signed evidence is verified by submitting test data that matches or mismatches the source and observing the proofing outcome."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of proofing notifications to validated addresses is verified by completing the IAL2 proofing process and checking for the notification delivery."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of knowledge-based verification is verified by inspecting the code and configuration to ensure no such mechanism is implemented or enabled."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The prohibition of email for out-of-band authentication is verified by inspecting the authentication logic and configuration to ensure email is not used as an OOB factor."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "The 5-minute validity window for SMS codes is verified by submitting a correct code after 5 minutes and observing the rejection, and before 5 minutes and observing success."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "The single-use nature of SMS codes is verified by submitting a valid code twice and observing that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "The non-resetting of failed authentication counts upon generating a new SMS code is verified by failing authentication, requesting a new code, and checking that the failure count remains unchanged."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "The absence of additional password composition requirements is verified by setting passwords that meet length and blocklist criteria but lack specific character classes, and observing their acceptance."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "ETC-051",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies dynamic data replacement logic upon receiving new track descriptions, which must be verified by executing the system with specific input sequences and observing the stored data state."
    },
    {
      "requirement_id": "ETC-052",
      "methods": [
        "Test"
      ],
      "rationale": "This requirement defines the OBU's response to specific trackside requests for resetting states, which is best verified by simulating these requests and checking the resulting state changes."
    },
    {
      "requirement_id": "ETC-053",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior depends on the direction of the Supervised Manoeuvre relative to train orientation, requiring a functional test to verify the conditional application of replacement rules or deletion."
    },
    {
      "requirement_id": "ETC-054",
      "methods": [
        "Test"
      ],
      "rationale": "This requirement involves time-dependent logic for MA request parameters and immediate triggering conditions, which must be verified through functional testing with controlled timing and parameter updates."
    },
    {
      "requirement_id": "ETC-055",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement mandates including all applicable reasons in MA requests, which can be verified by triggering various conditions and inspecting the content of the sent messages."
    },
    {
      "requirement_id": "ETC-056",
      "methods": [
        "Test"
      ],
      "rationale": "Triggering MA requests based on location passage or timer expiration requires functional testing to confirm the OBU sends requests at the correct events."
    },
    {
      "requirement_id": "ETC-057",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies sending MA requests upon specific track description deletions in Level 2, which is verified by simulating these deletion scenarios and monitoring communication."
    },
    {
      "requirement_id": "ETC-058",
      "methods": [
        "Test"
      ],
      "rationale": "Starting the End Section timer upon passing a specific location is a dynamic behavior that must be verified by moving the train past the location and observing the timer state."
    },
    {
      "requirement_id": "ETC-059",
      "methods": [
        "Test"
      ],
      "rationale": "The consequences of the End Section timer timeout, including withdrawing EOA/LOA and deleting information, are functional behaviors verified by allowing the timer to expire and checking the system state."
    },
    {
      "requirement_id": "ETC-060",
      "methods": [
        "Test"
      ],
      "rationale": "The start conditions for the LOA speed timer differ between Level 1 and Level 2, requiring functional tests in both modes to verify correct timer initiation."
    },
    {
      "requirement_id": "ETC-061",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement defines the system's response to LOA speed timer timeout, including speed setting and data deletion, which is verified by functional testing of the timeout event."
    },
    {
      "requirement_id": "ETC-062",
      "methods": [
        "Test"
      ],
      "rationale": "Starting the Overlap timer upon passing a location, including the special case of an 'infinite' timeout value, is a functional behavior verified by testing these specific scenarios."
    },
    {
      "requirement_id": "ETC-063",
      "methods": [
        "Test"
      ],
      "rationale": "The actions taken upon Overlap timer timeout, such as deleting overlap and redetermining Supervised Location, are functional behaviors verified by allowing the timer to expire."
    },
    {
      "requirement_id": "ETC-064",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies that a train standstill after the Overlap timer starts is treated as a timeout, which is verified by simulating a stop and checking the resulting system actions."
    },
    {
      "requirement_id": "ETC-065",
      "methods": [
        "Test"
      ],
      "rationale": "This edge case involves receiving a new MA with a rearward Overlap timer start location, requiring a functional test to verify the OBU treats it as a timeout."
    },
    {
      "requirement_id": "ETC-066",
      "methods": [
        "Test"
      ],
      "rationale": "The logic for selecting the Supervised Location based on the existence and status of overlap, Danger Point, or End Section is a functional decision process verified by testing various combinations of these states."
    },
    {
      "requirement_id": "ETC-067",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement prohibits defining a Supervised Location while supervising an LOA, which is verified by entering this state and confirming that no SvL is active."
    },
    {
      "requirement_id": "ETC-068",
      "methods": [
