{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Setting a new phone number triggers authenticator binding process",
      "covers": [
        "KDH-009"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a pre-registered telephone number. The user is authenticated.",
      "test_inputs": "New valid telephone number.",
      "assumptions": "The system implements the NIST SP 800-63B-4 §4.1.2 binding process as defined in §3.1.3.3, which typically involves sending a verification code to the new number.",
      "steps": [
        {
          "no": 1,
          "action": "Navigate to the profile settings and select the option to change the pre-registered telephone number.",
          "expected": "The system initiates the authenticator binding process (e.g., prompts for a verification code to be sent to the new number) rather than simply saving the number."
        },
        {
          "no": 2,
          "action": "Enter the new telephone number and submit the request.",
          "expected": "The system sends a verification code to the new telephone number and does not update the profile until the code is verified."
        },
        {
          "no": 3,
          "action": "Enter the correct verification code received via SMS.",
          "expected": "The system successfully binds the new authenticator and updates the pre-registered telephone number in the profile."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Changing an existing phone number triggers authenticator binding process",
      "covers": [
        "KDH-009"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a pre-registered telephone number. The user is authenticated.",
      "test_inputs": "New valid telephone number different from the current one.",
      "assumptions": "The system treats 'changing' the number identically to 'setting' it in terms of security requirements.",
      "steps": [
        {
          "no": 1,
          "action": "Navigate to the profile settings and select the option to change the current pre-registered telephone number.",
          "expected": "The system initiates the authenticator binding process for the new number."
        },
        {
          "no": 2,
          "action": "Enter the new telephone number and submit the request.",
          "expected": "The system requires verification of the new number via the binding process (e.g., SMS code) before allowing the change."
        },
        {
          "no": 3,
          "action": "Complete the verification process with the correct code.",
          "expected": "The old telephone number is replaced by the new one, and the new number is bound as the authenticator."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Failure to complete binding process prevents phone number update",
      "covers": [
        "KDH-009"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a pre-registered telephone number. The user is authenticated.",
      "test_inputs": "New valid telephone number, incorrect verification code.",
      "assumptions": "The binding process requires a valid verification code to complete.",
      "steps": [
        {
          "no": 1,
          "action": "Initiate the change of the pre-registered telephone number to a new number.",
          "expected": "The system sends a verification code to the new number."
        },
        {
          "no": 2,
          "action": "Enter an incorrect verification code.",
          "expected": "The system rejects the code and displays an error message."
        },
        {
          "no": 3,
          "action": "Check the profile settings for the pre-registered telephone number.",
          "expected": "The pre-registered telephone number remains unchanged (still the old number)."
        }
      ]
    }
  ]
}

